#!/usr/bin/env python3
"""Apply reviewed fixes to the pinned SwiftTorrent revision; fail on source drift."""
from pathlib import Path
import json
root = Path("Vendor/SwiftTorrent")
changes = json.loads(r'''[{"path":"Sources/SwiftTorrent/PiecePicker/PieceManager.swift","old":"    private var pieceBuffers: [Int: Data]","new":"    private var pieceBuffers: [Int: Data]\n    private var receivedBlocks: [Int: Set<Int>] = [:]"},{"path":"Sources/SwiftTorrent/PiecePicker/PieceManager.swift","old":"        pieceBuffers[index] = Data()","new":"        pieceBuffers[index] = Data()\n        receivedBlocks[index] = []"},{"path":"Sources/SwiftTorrent/PiecePicker/PieceManager.swift","old":"        guard var buffer = pieceBuffers[pieceIndex] else { return }","new":"        guard pieceIndex >= 0, pieceIndex < pieceCount,\n              offset >= 0, offset % 16384 == 0,\n              data.count == min(16384, expectedPieceSize(pieceIndex) - offset),\n              var buffer = pieceBuffers[pieceIndex] else { return }"},{"path":"Sources/SwiftTorrent/PiecePicker/PieceManager.swift","old":"        pieceBuffers[pieceIndex] = buffer","new":"        pieceBuffers[pieceIndex] = buffer\n        receivedBlocks[pieceIndex, default: []].insert(offset)"},{"path":"Sources/SwiftTorrent/PiecePicker/PieceManager.swift","old":"        guard let buffer = pieceBuffers[index] else { return false }","new":"        guard isPieceFullyReceived(index), let buffer = pieceBuffers[index] else { return false }"},{"path":"Sources/SwiftTorrent/PiecePicker/PieceManager.swift","old":"            pieceBuffers.removeValue(forKey: index)","new":"            pieceBuffers.removeValue(forKey: index)\n            receivedBlocks.removeValue(forKey: index)"},{"path":"Sources/SwiftTorrent/PiecePicker/PieceManager.swift","old":"        completed.set(index)","new":"        receivedBlocks.removeValue(forKey: index)\n        completed.set(index)"},{"path":"Sources/SwiftTorrent/PiecePicker/PieceManager.swift","old":"    /// Get the completed bitfield.","new":"    public func hasBlock(pieceIndex: Int, offset: Int) -> Bool {\n        receivedBlocks[pieceIndex]?.contains(offset) == true\n    }\n\n    public func isPieceFullyReceived(_ index: Int) -> Bool {\n        guard index >= 0, index < pieceCount else { return false }\n        return receivedBlocks[index]?.count == blockCount(for: index)\n    }\n\n    /// Get the completed bitfield."},{"path":"Sources/SwiftTorrent/Peer/PeerManager.swift","old":"        peerInfos[key] = PeerInfo(id: Data(), address: address, port: port)","new":"        peerInfos[key] = PeerInfo(id: Data(), address: address, port: port)\n        // Prepare state before inbound messages can arrive.\n        peerStates[key] = PeerState(pieceCount: pieceCount > 0 ? pieceCount : 1)"},{"path":"Sources/SwiftTorrent/Peer/PeerManager.swift","old":"        let pc = pieceCount > 0 ? pieceCount : 1\n        let state = PeerState(pieceCount: pc)","new":"        guard let state = peerStates[key] else { return }"},{"path":"Sources/SwiftTorrent/Peer/PeerManager.swift","old":"            let request = PeerState.BlockRequest(pieceIndex: pieceIndex, offset: offset, length: block.count)\n            await state.removePendingRequest(request)","new":"            let request = PeerState.BlockRequest(pieceIndex: pieceIndex, offset: offset, length: block.count)\n            guard await state.hasPending(request) else { break }\n            await state.removePendingRequest(request)"},{"path":"Sources/SwiftTorrent/Peer/PeerManager.swift","old":"            if let buf = buffer, buf.count >= expectedSize {","new":"            if let buf = buffer, buf.count >= expectedSize, await pm.isPieceFullyReceived(pieceIndex) {"},{"path":"Sources/SwiftTorrent/Peer/PeerManager.swift","old":"                if !(await state.hasPending(request)) {","new":"                let pending = await state.hasPending(request)\n                let received = await pm.hasBlock(pieceIndex: pieceIndex, offset: offset)\n                if !pending && !received {"},{"path":"Sources/SwiftTorrent/Peer/PeerConnection.swift","old":"        let decoder = PeerMessageDecoder()","new":"        let decoder = PeerMessageDecoder(expectedInfoHash: infoHash)"},{"path":"Sources/SwiftTorrent/Peer/PeerConnection.swift","old":"                return channel.pipeline.addHandlers([decoderHandler, messageHandler])","new":"                self.setChannel(channel)\n                return channel.pipeline.addHandlers([decoderHandler, PeerMessageEncoder(), messageHandler])"},{"path":"Sources/SwiftTorrent/Peer/PeerConnection.swift","old":"        try await ch.writeAndFlush(buffer).get()\n\n        // Add the message encoder after handshake is sent\n        try await ch.pipeline.addHandler(PeerMessageEncoder()).get()","new":"        // Write raw handshake bytes before the encoder in the outbound pipeline.\n        let encoderContext = try await ch.pipeline.context(handlerType: PeerMessageEncoder.self).get()\n        try await ch.eventLoop.submit {\n            let promise = ch.eventLoop.makePromise(of: Void.self)\n            encoderContext.writeAndFlush(NIOAny(buffer), promise: promise)\n            return promise.futureResult\n        }.flatMap { $0 }.get()"},{"path":"Sources/SwiftTorrent/Peer/PeerConnection.swift","old":"    private var handshakeReceived = false","new":"    private var handshakeReceived = false\n    private let expectedInfoHash: Data?\n    init(expectedInfoHash: Data? = nil) { self.expectedInfoHash = expectedInfoHash }"},{"path":"Sources/SwiftTorrent/Peer/PeerConnection.swift","old":"            let handshake = try Handshake.decode(from: Data(bytes))","new":"            let handshake = try Handshake.decode(from: Data(bytes))\n            if let expectedInfoHash, handshake.infoHash != expectedInfoHash { throw PeerConnectionError.handshakeFailed }"},{"path":"Sources/SwiftTorrent/Session/TorrentHandle.swift","old":"numPeers: await peerManager.connectionCount,","new":"numPeers: await peerManager.connectedCount,"}]''')
for change in changes:
    path = root / change["path"]
    source = path.read_text()
    if source.count(change["old"]) != 1:
        raise SystemExit("Patch precondition failed: " + change["path"])
    path.write_text(source.replace(change["old"], change["new"], 1))
